package com.bustramnantes.app.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Update
import com.bustramnantes.app.data.local.entity.RecentSearchEntity
import kotlinx.coroutines.flow.Flow

@Dao
interface RecentSearchDao {

    /** Returns the autogenerated row id of the inserted entry. */
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(recentSearch: RecentSearchEntity): Long

    @Query("SELECT * FROM recent_search ORDER BY searchedAt DESC")
    fun observeAll(): Flow<List<RecentSearchEntity>>

    @Query("DELETE FROM recent_search WHERE id = :id")
    suspend fun deleteById(id: Long)

    @Query("DELETE FROM recent_search")
    suspend fun clearAll()

    @Query("SELECT * FROM recent_search")
    suspend fun getAll(): List<RecentSearchEntity>

    @Update
    suspend fun updateAll(entries: List<RecentSearchEntity>)

    /** Enforces the 10-entry cap: deletes all but the [cap] most recent rows. */
    @Query(
        "DELETE FROM recent_search WHERE id NOT IN " +
            "(SELECT id FROM recent_search ORDER BY searchedAt DESC LIMIT :cap)"
    )
    suspend fun trimToCap(cap: Int = 10)
}
